mapper.select:
SELECT count(*)
FROM sys_dept d1

    JOIN sys_dept d2 ON d2.parent_id = d1.id


    JOIN sys_dept d3 ON d3.parent_id = d2.id

WHERE d1.id = #{collegeId}
  AND d1.university_id = #{universityId}
  AND d1.dept_type = 1

  AND d2.id = #{majorId}
  AND d2.university_id = #{universityId}
  AND d2.dept_type = 2


  AND d3.id = #{classId}
  AND d3.university_id = #{universityId}
  AND d3.dept_type = 3

SELECT id, name, dept_type AS deptType, parent_id AS parentId, university_id AS universityId
FROM sys_dept
WHERE id = #{id}

select count(*)
from sys_dept
where parent_id = #{parentId}

SELECT d.id, d.name, d.dept_type AS deptType, d.parent_id AS parentId, d.university_id AS universityId, u.name AS universityName, p.name AS parentName FROM sys_dept d left join universities u on d.university_id = u.id left join sys_dept p on d.parent_id = p.id
and d.university_id = #{universityId}
and d.dept_type = #{deptType}
and d.parent_id = #{parentId}
and d.name like concat('%', #{name}, '%')
order by d.id desc
